                    {
                        countdown.AddCount();
                        var start = chunk * chunkSize;
                        var length = Math.Min(chunkSize, count - start);

                        var (s0, s1) = join.Select;
                        var job = JobPool<UniformDualWork<U, C0, C1>>.Rent();
                        job.Memory1 = s0.AsMemory(start, length);
                        job.Memory2 = s1.AsMemory(start, length);
                        job.Included = action;
                        job.Excluded = null;
                        job.Pass = pass;
                        job.Uniform = uniform;
                        job.CountDown = countdown;
                        jobs.Add(job);

                        ThreadPool.UnsafeQueueUserWorkItem(job, true);
                    }
                } while (join.Iterate());
            }
            countdown.Signal();
            countdown.Wait();

            List<Exception>? faults = null;
            Workloads.CollectFaults(ref faults, jobs);
            foreach (var job in jobs)
            {
                job.Memory1 = default;
                job.Memory2 = default;
                job.Pass = null!;
                job.Included = null!;
                job.Excluded = null;
                job.Uniform = default!;
                job.CountDown = null!;
            }
            JobPool<UniformDualWork<U, C0, C1>>.Return(jobs);
