        #endregion

        #region IEnumerable
        /// <inheritdoc />
        public IEnumerator<(Entity, C0, C1)> GetEnumerator()
        {
            foreach (var table in Archetypes)
            {
                if (!Includes(table)) continue;
                using var join = table.CrossJoin<C0, C1>(Stream.StreamTypes.AsSpan());
                if (join.Empty) continue;
                var snapshot = table.Version;
                do
                {
                    var (s0, s1) = join.Select;
                    for (var i = 0; i < table.Count; i++)
                    {
                        if (!Pass(s0[i], s1[i])) continue;
                        yield return (table[i], s0[i], s1[i]);
                        if (table.Version != snapshot) throw new InvalidOperationException("Collection was modified during iteration.");
                    }
                } while (join.Iterate());
            }
        }
        IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
        #endregion

        #region Despawn
        /// <summary>
        /// Despawn all Entities matched by this FilteredStream, honoring all filters.
        /// </summary>
        /// <remarks>
        /// With per-entity predicates set, this is not supported on wildcard Stream Types.
        /// </remarks>
        public void Despawn()
        {
            if (!HasPredicates)
            {
                // Loop because Truncate side effects (e.g. relation cleanup) can migrate
                // entities into matched archetypes.
                while (IncludedCount > 0)
                {
                    using var worldLock = World.Lock();
                    foreach (var table in Archetypes)
                    {
                        if (Includes(table)) table.Truncate(0);
                    }
                }
                return;
            }

            AssertNoWildcards();
            using var doomed = PooledList<Entity>.Rent();
            using (var worldLock = World.Lock())
            {
                foreach (var table in Archetypes)
                {
                    if (!Includes(table)) continue;
                    using var join = table.CrossJoin<C0, C1>(Stream.StreamTypes.AsSpan());
                    if (join.Empty) continue;
                    do
                    {
                        var (s0, s1) = join.Select;
                        Collect(table, s0.Span, s1.Span, doomed);
                    } while (join.Iterate());
                }
            }
            foreach (var entity in doomed)
            {
                if (entity.Alive) World.Despawn(entity);
            }
        }

        private void Collect(Archetype table, Span<C0> span0, Span<C1> span1, PooledList<Entity> doomed)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                if (Pass(in span0[i], in span1[i])) doomed.Add(table[i]);
            }
        }
        #endregion

        #region Action Loops
        private void Loop(Span<C0> span0, Span<C1> span1, ComponentAction<C0, C1> action)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                if (!Pass(in span0[i], in span1[i])) continue;
                action(ref span0[i], ref span1[i]);
            }
        }

        private void LoopEntity(Archetype table, Span<C0> span0, Span<C1> span1, EntityComponentAction<C0, C1> action)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                if (!Pass(in span0[i], in span1[i])) continue;
                action(new EntityRef(table, i), ref span0[i], ref span1[i]);
            }
        }

        private void LoopUniform<U>(Span<C0> span0, Span<C1> span1, UniformComponentAction<U, C0, C1> action, U uniform)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                if (!Pass(in span0[i], in span1[i])) continue;
                action(uniform, ref span0[i], ref span1[i]);
            }
        }

        private void LoopUniformEntity<U>(Archetype table, Span<C0> span0, Span<C1> span1, UniformEntityComponentAction<U, C0, C1> action, U uniform)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                if (!Pass(in span0[i], in span1[i])) continue;
                action(uniform, new EntityRef(table, i), ref span0[i], ref span1[i]);
            }
        }

        private void LoopDual(Span<C0> span0, Span<C1> span1, ComponentAction<C0, C1> included, ComponentAction<C0, C1> excluded)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                if (Pass(in span0[i], in span1[i])) included(ref span0[i], ref span1[i]);
                else excluded(ref span0[i], ref span1[i]);
            }
        }

        private void LoopDualEntity(Archetype table, Span<C0> span0, Span<C1> span1, EntityComponentAction<C0, C1> included, EntityComponentAction<C0, C1> excluded)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                if (Pass(in span0[i], in span1[i])) included(new EntityRef(table, i), ref span0[i], ref span1[i]);
                else excluded(new EntityRef(table, i), ref span0[i], ref span1[i]);
            }
        }

        private void LoopDualUniform<U>(Span<C0> span0, Span<C1> span1, UniformComponentAction<U, C0, C1> included, UniformComponentAction<U, C0, C1> excluded, U uniform)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                if (Pass(in span0[i], in span1[i])) included(uniform, ref span0[i], ref span1[i]);
                else excluded(uniform, ref span0[i], ref span1[i]);
            }
        }

        private void LoopDualUniformEntity<U>(Archetype table, Span<C0> span0, Span<C1> span1, UniformEntityComponentAction<U, C0, C1> included, UniformEntityComponentAction<U, C0, C1> excluded, U uniform)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                if (Pass(in span0[i], in span1[i])) included(uniform, new EntityRef(table, i), ref span0[i], ref span1[i]);
                else excluded(uniform, new EntityRef(table, i), ref span0[i], ref span1[i]);
            }
        }

        private static void LoopAll(Span<C0> span0, Span<C1> span1, ComponentAction<C0, C1> action)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                action(ref span0[i], ref span1[i]);
            }
        }

        private static void LoopAllEntity(Archetype table, Span<C0> span0, Span<C1> span1, EntityComponentAction<C0, C1> action)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                action(new EntityRef(table, i), ref span0[i], ref span1[i]);
            }
        }

        private static void LoopAllUniform<U>(Span<C0> span0, Span<C1> span1, UniformComponentAction<U, C0, C1> action, U uniform)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                action(uniform, ref span0[i], ref span1[i]);
            }
        }

        private static void LoopAllUniformEntity<U>(Archetype table, Span<C0> span0, Span<C1> span1, UniformEntityComponentAction<U, C0, C1> action, U uniform)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                action(uniform, new EntityRef(table, i), ref span0[i], ref span1[i]);
            }
        }
        #endregion

        #region Internals

        // Sum of entity counts of all included archetypes (predicates not evaluated).
        private int IncludedCount
        {
            get
            {
                var sum = 0;
                foreach (var table in Archetypes)
                {
                    if (Includes(table)) sum += table.Count;
                }
                return sum;
            }
        }

        private bool HasWildcards => Stream.StreamTypes.Any(type => type.isWildcard);

        private void AssertNoWildcards()
        {
            if (HasWildcards)
                throw new InvalidOperationException(
                    $"Cannot run this operation on wildcard Stream Types (write destination Aliasing). {Stream.StreamTypes}");
        }

        /// <inheritdoc />
        public override string ToString() =>
            $"FilteredStream<{string.Join(", ", Stream.StreamTypes)}>(Has: {_has.Count}, Not: {_not.Count}, Where: {(_filter0 is null ? 0 : 1) + (_filter1 is null ? 0 : 1)})";
        #endregion
    }
    /// <summary>
    /// A filtered view over a <see cref="Stream{C0, C1, C2}"/> with arity 3.
    /// Narrows the underlying Query by Archetype (<see cref="Has"/>, <see cref="Not"/>)
    /// and by per-entity component predicates (<see cref="Where(ComponentFilter{C0})"/>).
    /// </summary>
    /// <remarks>
    /// Two-delegate runner overloads visit the complement, too: <c>included</c> runs on every
    /// entity passing all filters, <c>excluded</c> on every other entity the Query matches.
    /// </remarks>
    public readonly struct FilteredStream<C0, C1, C2>
        : IEnumerable<(Entity, C0, C1, C2)>
        
    where C0 : notnull
    where C1 : notnull
    where C2 : notnull
    {
        #region Fields & Properties

        /// <summary>
        /// The underlying, unfiltered Stream. Use this to run operations that cannot honor
        /// per-entity predicates, such as <c>Raw</c> and <c>Blit</c>.
        /// </summary>
        public Stream<C0, C1, C2> Stream { get; }

        // Archetype-level filters: Has requires ALL, Not rejects ANY of the expressions.
        private readonly ImmutableSortedSet<Comp> _has;
        private readonly ImmutableSortedSet<Comp> _not;

        // The above, compiled to bit-testable clauses once at construction for Archetype matching.
        private readonly ClauseBits _hasBits;
        private readonly ClauseBits _notBits;

        // Per-entity predicate for C0; null means unset (all entities pass).
        private readonly ComponentFilter<C0>? _filter0;
        // Per-entity predicate for C1; null means unset (all entities pass).
        private readonly ComponentFilter<C1>? _filter1;
        // Per-entity predicate for C2; null means unset (all entities pass).
        private readonly ComponentFilter<C2>? _filter2;

        private Query Query => Stream.Query;

        private SortedSet<Archetype> Archetypes => Query.Archetypes;

        private World World => Query.World;

        private static int Concurrency => Math.Max(1, Environment.ProcessorCount - 2);

        private bool HasPredicates => _filter0 is not null || _filter1 is not null || _filter2 is not null;

        /// <summary>
        /// The number of entities matched by this FilteredStream, honoring all filters.
        /// </summary>
        /// <remarks>
        /// With per-entity predicates set, this is O(n), evaluating the predicates for each entity.
        /// (for wildcard Stream Types, entities are counted once per matched permutation)
        /// </remarks>
        public int Count
        {
            get
            {
                // Wildcard-less streams visit each entity exactly once, so archetype totals suffice.
                if (!HasPredicates && !HasWildcards) return IncludedCount;

                using var worldLock = World.Lock();
                var count = 0;
                foreach (var table in Archetypes)
                {
                    if (!Includes(table)) continue;
                    using var join = table.CrossJoin<C0, C1, C2>(Stream.StreamTypes.AsSpan());
                    if (join.Empty) continue;
                    do
                    {
                        if (HasPredicates)
                        {
                            var (s0, s1, s2) = join.Select;
                            count += CountPass(s0.Span, s1.Span, s2.Span);
                        }
                        else
                        {
                            count += table.Count;
                        }
                    } while (join.Iterate());
                }
                return count;
            }
        }
        #endregion

        #region Constructor

        internal FilteredStream(Stream<C0, C1, C2> stream,
            ImmutableSortedSet<Comp> has,
            ImmutableSortedSet<Comp> not,
            ComponentFilter<C0>? filter0, ComponentFilter<C1>? filter1, ComponentFilter<C2>? filter2)
        {
            Stream = stream;
            _has = has;
            _not = not;
            _hasBits = ClauseBits.Of(has.Select(comp => comp.Expression));
            _notBits = ClauseBits.Of(not.Select(comp => comp.Expression));
            _filter0 = filter0;
            _filter1 = filter1;
            _filter2 = filter2;
        }
        #endregion

        #region Fluent Filter Builders

        /// <summary>
        /// Narrows this FilteredStream to Archetypes that have ALL of the given components,
        /// in addition to any previously required ones.
        /// </summary>
        public FilteredStream<C0, C1, C2> Has(params Comp[] components) =>
            new(Stream, _has.Union(components), _not, _filter0, _filter1, _filter2);

        /// <summary>
        /// Narrows this FilteredStream to Archetypes that have NONE of the given components,
        /// in addition to any previously rejected ones.
        /// </summary>
        public FilteredStream<C0, C1, C2> Not(params Comp[] components) =>
            new(Stream, _has, _not.Union(components), _filter0, _filter1, _filter2);

        /// <summary>
        /// Creates a new FilteredStream with the same filters, but replacing the
        /// per-entity predicate for Component <c>C0</c> with the provided one.
        /// </summary>
        public FilteredStream<C0, C1, C2> Where(ComponentFilter<C0> filter0) =>
            new(Stream, _has, _not, filter0, _filter1, _filter2);

        /// <summary>
        /// Creates a new FilteredStream with the same filters, but replacing the
        /// per-entity predicate for Component <c>C1</c> with the provided one.
        /// </summary>
        public FilteredStream<C0, C1, C2> Where(ComponentFilter<C1> filter1) =>
            new(Stream, _has, _not, _filter0, filter1, _filter2);

        /// <summary>
        /// Creates a new FilteredStream with the same filters, but replacing the
        /// per-entity predicate for Component <c>C2</c> with the provided one.
        /// </summary>
        public FilteredStream<C0, C1, C2> Where(ComponentFilter<C2> filter2) =>
            new(Stream, _has, _not, _filter0, _filter1, filter2);
        #endregion

        #region Filter Logic

        // Conjunction of all set per-entity predicates; also serves as the Job FilterDelegate.
        private bool Pass(in C0 c0, in C1 c1, in C2 c2) =>
            (_filter0 is null || _filter0(in c0)) && (_filter1 is null || _filter1(in c1)) && (_filter2 is null || _filter2(in c2));

        // Archetype-level inclusion: must have ALL of Has, and NONE of Not.
        private bool Includes(Archetype candidate) =>
            candidate.Bits.IsSupersetOf(_hasBits) && !candidate.Bits.Overlaps(_notBits);

        private int CountPass(Span<C0> span0, Span<C1> span1, Span<C2> span2)
        {
            var count = 0;
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                if (Pass(in span0[i], in span1[i], in span2[i])) count++;
            }
            return count;
        }
        #endregion

        #region For
        /// <include file='../XMLdoc.xml' path='members/member[@name="T:For"]'/>
        public void For(ComponentAction<C0, C1, C2> action)
        {
            using var worldLock = World.Lock();
            foreach (var table in Archetypes)
            {
                if (!Includes(table)) continue;
                using var join = table.CrossJoin<C0, C1, C2>(Stream.StreamTypes.AsSpan());
                if (join.Empty) continue;
                do
                {
                    var (s0, s1, s2) = join.Select;
                    Loop(s0.Span, s1.Span, s2.Span, action);
                } while (join.Iterate());
            }
        }

        /// <include file='../XMLdoc.xml' path='members/member[@name="T:ForU"]'/>
        public void For<U>(U uniform, UniformComponentAction<U, C0, C1, C2> action)
        {
            using var worldLock = World.Lock();
            foreach (var table in Archetypes)
            {
                if (!Includes(table)) continue;
                using var join = table.CrossJoin<C0, C1, C2>(Stream.StreamTypes.AsSpan());
                if (join.Empty) continue;
                do
                {
                    var (s0, s1, s2) = join.Select;
                    LoopUniform(s0.Span, s1.Span, s2.Span, action, uniform);
                } while (join.Iterate());
            }
        }

        /// <include file='../XMLdoc.xml' path='members/member[@name="T:ForE"]'/>
        public void For(EntityComponentAction<C0, C1, C2> action)
        {
            using var worldLock = World.Lock();
            foreach (var table in Archetypes)
            {
                if (!Includes(table)) continue;
                using var join = table.CrossJoin<C0, C1, C2>(Stream.StreamTypes.AsSpan());
                if (join.Empty) continue;
                do
                {
                    var (s0, s1, s2) = join.Select;
                    LoopEntity(table, s0.Span, s1.Span, s2.Span, action);
                } while (join.Iterate());
            }
        }

        /// <include file='../XMLdoc.xml' path='members/member[@name="T:ForEU"]'/>
        public void For<U>(U uniform, UniformEntityComponentAction<U, C0, C1, C2> action)
        {
            using var worldLock = World.Lock();
            foreach (var table in Archetypes)
            {
                if (!Includes(table)) continue;
                using var join = table.CrossJoin<C0, C1, C2>(Stream.StreamTypes.AsSpan());
                if (join.Empty) continue;
                do
                {
                    var (s0, s1, s2) = join.Select;
                    LoopUniformEntity(table, s0.Span, s1.Span, s2.Span, action, uniform);
                } while (join.Iterate());
            }
        }
        #endregion

        #region For (included, excluded)
        /// <summary>
        /// Executes <paramref name="included"/> for each entity passing all filters, and
        /// <paramref name="excluded"/> for each other entity matched by the underlying Query.
        /// </summary>
        /// <remarks>
        /// Together, both delegates visit every entity of the Query exactly once.
        /// Not supported on wildcard Stream Types.
        /// </remarks>
        public void For(ComponentAction<C0, C1, C2> included, ComponentAction<C0, C1, C2> excluded)
        {
            AssertNoWildcards();
            using var worldLock = World.Lock();
            foreach (var table in Archetypes)
            {
                var covered = Includes(table);
                using var join = table.CrossJoin<C0, C1, C2>(Stream.StreamTypes.AsSpan());
                if (join.Empty) continue;
                do
                {
                    var (s0, s1, s2) = join.Select;
                    if (covered) LoopDual(s0.Span, s1.Span, s2.Span, included, excluded);
                    else LoopAll(s0.Span, s1.Span, s2.Span, excluded);
                } while (join.Iterate());
            }
        }

        /// <inheritdoc cref="For(ComponentAction{C0, C1, C2}, ComponentAction{C0, C1, C2})"/>
        public void For<U>(U uniform, UniformComponentAction<U, C0, C1, C2> included, UniformComponentAction<U, C0, C1, C2> excluded)
        {
            AssertNoWildcards();
            using var worldLock = World.Lock();
            foreach (var table in Archetypes)
            {
                var covered = Includes(table);
                using var join = table.CrossJoin<C0, C1, C2>(Stream.StreamTypes.AsSpan());
                if (join.Empty) continue;
                do
                {
                    var (s0, s1, s2) = join.Select;
                    if (covered) LoopDualUniform(s0.Span, s1.Span, s2.Span, included, excluded, uniform);
                    else LoopAllUniform(s0.Span, s1.Span, s2.Span, excluded, uniform);
                } while (join.Iterate());
            }
        }

        /// <inheritdoc cref="For(ComponentAction{C0, C1, C2}, ComponentAction{C0, C1, C2})"/>
        public void For(EntityComponentAction<C0, C1, C2> included, EntityComponentAction<C0, C1, C2> excluded)
        {
            AssertNoWildcards();
            using var worldLock = World.Lock();
            foreach (var table in Archetypes)
            {
                var covered = Includes(table);
                using var join = table.CrossJoin<C0, C1, C2>(Stream.StreamTypes.AsSpan());
                if (join.Empty) continue;
                do
                {
                    var (s0, s1, s2) = join.Select;
                    if (covered) LoopDualEntity(table, s0.Span, s1.Span, s2.Span, included, excluded);
                    else LoopAllEntity(table, s0.Span, s1.Span, s2.Span, excluded);
                } while (join.Iterate());
            }
        }

        /// <inheritdoc cref="For(ComponentAction{C0, C1, C2}, ComponentAction{C0, C1, C2})"/>
        public void For<U>(U uniform, UniformEntityComponentAction<U, C0, C1, C2> included, UniformEntityComponentAction<U, C0, C1, C2> excluded)
        {
            AssertNoWildcards();
            using var worldLock = World.Lock();
            foreach (var table in Archetypes)
            {
                var covered = Includes(table);
                using var join = table.CrossJoin<C0, C1, C2>(Stream.StreamTypes.AsSpan());
                if (join.Empty) continue;
                do
                {
                    var (s0, s1, s2) = join.Select;
                    if (covered) LoopDualUniformEntity(table, s0.Span, s1.Span, s2.Span, included, excluded, uniform);
                    else LoopAllUniformEntity(table, s0.Span, s1.Span, s2.Span, excluded, uniform);
                } while (join.Iterate());
            }
        }
        #endregion

        #region Job
        /// <summary>
        /// Executes the action in parallel on the thread pool for each entity passing all filters.
        /// </summary>
        /// <remarks>
        /// Not supported on wildcard Stream Types. The action must be thread-safe.
        /// </remarks>
        /// <exception cref="AggregateException">if any worker threw; raised after all workers have finished</exception>
        [UnsupportedOSPlatform("browser", "browser-wasm runtime is single-threaded")]
        public void Job(ComponentAction<C0, C1, C2> action)
        {
            AssertNoWildcards();
            using var worldLock = World.Lock();
            var chunkSize = Math.Max(1, IncludedCount / Concurrency);

            using var countdown = new CountdownEvent(initialCount: 1);
            using var jobs = PooledList<DualWork<C0, C1, C2>>.Rent();
            FilterDelegate<C0, C1, C2> pass = Pass;

            foreach (var table in Archetypes)
            {
                if (!Includes(table)) continue;
                using var join = table.CrossJoin<C0, C1, C2>(Stream.StreamTypes.AsSpan());
                if (join.Empty) continue;
                var count = table.Count;
                var partitions = count / chunkSize + Math.Sign(count % chunkSize);

                do
                {
                    for (var chunk = 0; chunk < partitions; chunk++)
                    {
                        countdown.AddCount();
                        var start = chunk * chunkSize;
                        var length = Math.Min(chunkSize, count - start);

                        var (s0, s1, s2) = join.Select;
                        var job = JobPool<DualWork<C0, C1, C2>>.Rent();
                        job.Memory1 = s0.AsMemory(start, length);
                        job.Memory2 = s1.AsMemory(start, length);
                        job.Memory3 = s2.AsMemory(start, length);
                        job.Included = action;
                        job.Excluded = null;
                        job.Pass = pass;
                        job.CountDown = countdown;
                        jobs.Add(job);

                        ThreadPool.UnsafeQueueUserWorkItem(job, true);
                    }
                } while (join.Iterate());
            }
            countdown.Signal();
            countdown.Wait();

            List<Exception>? faults = null;
            Workloads.CollectFaults(ref faults, jobs);
            foreach (var job in jobs)
            {
                job.Memory1 = default;
                job.Memory2 = default;
                job.Memory3 = default;
                job.Pass = null!;
                job.Included = null!;
                job.Excluded = null;
                job.CountDown = null!;
            }
            JobPool<DualWork<C0, C1, C2>>.Return(jobs);
            Workloads.Rethrow(faults);
        }

        /// <inheritdoc cref="Job(ComponentAction{C0, C1, C2})"/>
        [UnsupportedOSPlatform("browser", "browser-wasm runtime is single-threaded")]
        public void Job<U>(U uniform, UniformComponentAction<U, C0, C1, C2> action)
        {
            AssertNoWildcards();
            using var worldLock = World.Lock();
            var chunkSize = Math.Max(1, IncludedCount / Concurrency);

            using var countdown = new CountdownEvent(initialCount: 1);
            using var jobs = PooledList<UniformDualWork<U, C0, C1, C2>>.Rent();
            FilterDelegate<C0, C1, C2> pass = Pass;

            foreach (var table in Archetypes)
            {
                if (!Includes(table)) continue;
                using var join = table.CrossJoin<C0, C1, C2>(Stream.StreamTypes.AsSpan());
                if (join.Empty) continue;
                var count = table.Count;
                var partitions = count / chunkSize + Math.Sign(count % chunkSize);

                do
                {
                    for (var chunk = 0; chunk < partitions; chunk++)
                    {
                        countdown.AddCount();
                        var start = chunk * chunkSize;
                        var length = Math.Min(chunkSize, count - start);

                        var (s0, s1, s2) = join.Select;
                        var job = JobPool<UniformDualWork<U, C0, C1, C2>>.Rent();
                        job.Memory1 = s0.AsMemory(start, length);
                        job.Memory2 = s1.AsMemory(start, length);
                        job.Memory3 = s2.AsMemory(start, length);
                        job.Included = action;
                        job.Excluded = null;
                        job.Pass = pass;
                        job.Uniform = uniform;
                        job.CountDown = countdown;
                        jobs.Add(job);

                        ThreadPool.UnsafeQueueUserWorkItem(job, true);
                    }
                } while (join.Iterate());
            }
            countdown.Signal();
            countdown.Wait();

            List<Exception>? faults = null;
            Workloads.CollectFaults(ref faults, jobs);
            foreach (var job in jobs)
            {
                job.Memory1 = default;
                job.Memory2 = default;
                job.Memory3 = default;
                job.Pass = null!;
                job.Included = null!;
                job.Excluded = null;
                job.Uniform = default!;
                job.CountDown = null!;
            }
            JobPool<UniformDualWork<U, C0, C1, C2>>.Return(jobs);
            Workloads.Rethrow(faults);
        }
        #endregion

        #region Job (included, excluded)
        /// <summary>
        /// Executes <paramref name="included"/> in parallel on the thread pool for each entity
        /// passing all filters, and <paramref name="excluded"/> for each other entity matched
        /// by the underlying Query.
        /// </summary>
        /// <remarks>
        /// Together, both delegates visit every entity of the Query exactly once.
        /// Not supported on wildcard Stream Types. The actions must be thread-safe.
        /// </remarks>
        /// <exception cref="AggregateException">if any worker threw; raised after all workers have finished</exception>
        [UnsupportedOSPlatform("browser", "browser-wasm runtime is single-threaded")]
        public void Job(ComponentAction<C0, C1, C2> included, ComponentAction<C0, C1, C2> excluded)
        {
            AssertNoWildcards();
            using var worldLock = World.Lock();
            var chunkSize = Math.Max(1, Query.Count / Concurrency);

            using var countdown = new CountdownEvent(initialCount: 1);
            using var dualJobs = PooledList<DualWork<C0, C1, C2>>.Rent();
            using var plainJobs = PooledList<Work<C0, C1, C2>>.Rent();
            FilterDelegate<C0, C1, C2> pass = Pass;

            foreach (var table in Archetypes)
            {
                var covered = Includes(table);
                using var join = table.CrossJoin<C0, C1, C2>(Stream.StreamTypes.AsSpan());
                if (join.Empty) continue;
                var count = table.Count;
                var partitions = count / chunkSize + Math.Sign(count % chunkSize);

                do
                {
                    for (var chunk = 0; chunk < partitions; chunk++)
                    {
                        countdown.AddCount();
                        var start = chunk * chunkSize;
                        var length = Math.Min(chunkSize, count - start);

                        var (s0, s1, s2) = join.Select;
                        if (covered)
                        {
                            var job = JobPool<DualWork<C0, C1, C2>>.Rent();
                            job.Memory1 = s0.AsMemory(start, length);
                            job.Memory2 = s1.AsMemory(start, length);
                            job.Memory3 = s2.AsMemory(start, length);
                            job.Included = included;
                            job.Excluded = excluded;
                            job.Pass = pass;
                            job.CountDown = countdown;
                            dualJobs.Add(job);

                            ThreadPool.UnsafeQueueUserWorkItem(job, true);
                        }
                        else
                        {
                            var job = JobPool<Work<C0, C1, C2>>.Rent();
                            job.Memory1 = s0.AsMemory(start, length);
                            job.Memory2 = s1.AsMemory(start, length);
                            job.Memory3 = s2.AsMemory(start, length);
                            job.Action = excluded;
                            job.CountDown = countdown;
                            plainJobs.Add(job);

                            ThreadPool.UnsafeQueueUserWorkItem(job, true);
                        }
                    }
                } while (join.Iterate());
            }
            countdown.Signal();
            countdown.Wait();

            List<Exception>? faults = null;
            Workloads.CollectFaults(ref faults, dualJobs);
            Workloads.CollectFaults(ref faults, plainJobs);
            foreach (var job in dualJobs)
            {
                job.Memory1 = default;
                job.Memory2 = default;
                job.Memory3 = default;
                job.Pass = null!;
                job.Included = null!;
                job.Excluded = null;
                job.CountDown = null!;
            }
            foreach (var job in plainJobs)
            {
                job.Memory1 = default;
                job.Memory2 = default;
                job.Memory3 = default;
                job.Action = null!;
                job.CountDown = null!;
            }
            JobPool<DualWork<C0, C1, C2>>.Return(dualJobs);
            JobPool<Work<C0, C1, C2>>.Return(plainJobs);
            Workloads.Rethrow(faults);
        }

        /// <inheritdoc cref="Job(ComponentAction{C0, C1, C2}, ComponentAction{C0, C1, C2})"/>
        [UnsupportedOSPlatform("browser", "browser-wasm runtime is single-threaded")]
        public void Job<U>(U uniform, UniformComponentAction<U, C0, C1, C2> included, UniformComponentAction<U, C0, C1, C2> excluded)
        {
            AssertNoWildcards();
            using var worldLock = World.Lock();
            var chunkSize = Math.Max(1, Query.Count / Concurrency);

            using var countdown = new CountdownEvent(initialCount: 1);
            using var dualJobs = PooledList<UniformDualWork<U, C0, C1, C2>>.Rent();
            using var plainJobs = PooledList<UniformWork<U, C0, C1, C2>>.Rent();
            FilterDelegate<C0, C1, C2> pass = Pass;

            foreach (var table in Archetypes)
            {
                var covered = Includes(table);
                using var join = table.CrossJoin<C0, C1, C2>(Stream.StreamTypes.AsSpan());
                if (join.Empty) continue;
                var count = table.Count;
                var partitions = count / chunkSize + Math.Sign(count % chunkSize);

                do
                {
                    for (var chunk = 0; chunk < partitions; chunk++)
                    {
                        countdown.AddCount();
                        var start = chunk * chunkSize;
                        var length = Math.Min(chunkSize, count - start);

                        var (s0, s1, s2) = join.Select;
                        if (covered)
                        {
                            var job = JobPool<UniformDualWork<U, C0, C1, C2>>.Rent();
                            job.Memory1 = s0.AsMemory(start, length);
                            job.Memory2 = s1.AsMemory(start, length);
                            job.Memory3 = s2.AsMemory(start, length);
                            job.Included = included;
                            job.Excluded = excluded;
                            job.Pass = pass;
                            job.Uniform = uniform;
                            job.CountDown = countdown;
                            dualJobs.Add(job);

                            ThreadPool.UnsafeQueueUserWorkItem(job, true);
                        }
                        else
                        {
                            var job = JobPool<UniformWork<U, C0, C1, C2>>.Rent();
                            job.Memory1 = s0.AsMemory(start, length);
                            job.Memory2 = s1.AsMemory(start, length);
                            job.Memory3 = s2.AsMemory(start, length);
                            job.Action = excluded;
                            job.Uniform = uniform;
                            job.CountDown = countdown;
                            plainJobs.Add(job);

                            ThreadPool.UnsafeQueueUserWorkItem(job, true);
                        }
                    }
                } while (join.Iterate());
            }
            countdown.Signal();
            countdown.Wait();

            List<Exception>? faults = null;
            Workloads.CollectFaults(ref faults, dualJobs);
            Workloads.CollectFaults(ref faults, plainJobs);
            foreach (var job in dualJobs)
            {
                job.Memory1 = default;
                job.Memory2 = default;
                job.Memory3 = default;
                job.Pass = null!;
                job.Included = null!;
                job.Excluded = null;
                job.Uniform = default!;
                job.CountDown = null!;
            }
            foreach (var job in plainJobs)
            {
                job.Memory1 = default;
                job.Memory2 = default;
                job.Memory3 = default;
                job.Action = null!;
                job.Uniform = default!;
                job.CountDown = null!;
            }
            JobPool<UniformDualWork<U, C0, C1, C2>>.Return(dualJobs);
            JobPool<UniformWork<U, C0, C1, C2>>.Return(plainJobs);
            Workloads.Rethrow(faults);
        }
        #endregion

        #region IEnumerable
        /// <inheritdoc />
        public IEnumerator<(Entity, C0, C1, C2)> GetEnumerator()
        {
            foreach (var table in Archetypes)
            {
                if (!Includes(table)) continue;
                using var join = table.CrossJoin<C0, C1, C2>(Stream.StreamTypes.AsSpan());
                if (join.Empty) continue;
                var snapshot = table.Version;
                do
                {
                    var (s0, s1, s2) = join.Select;
                    for (var i = 0; i < table.Count; i++)
                    {
                        if (!Pass(s0[i], s1[i], s2[i])) continue;
                        yield return (table[i], s0[i], s1[i], s2[i]);
                        if (table.Version != snapshot) throw new InvalidOperationException("Collection was modified during iteration.");
                    }
                } while (join.Iterate());
            }
        }
        IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
        #endregion

        #region Despawn
        /// <summary>
        /// Despawn all Entities matched by this FilteredStream, honoring all filters.
        /// </summary>
        /// <remarks>
        /// With per-entity predicates set, this is not supported on wildcard Stream Types.
        /// </remarks>
        public void Despawn()
        {
            if (!HasPredicates)
            {
                // Loop because Truncate side effects (e.g. relation cleanup) can migrate
                // entities into matched archetypes.
                while (IncludedCount > 0)
                {
                    using var worldLock = World.Lock();
                    foreach (var table in Archetypes)
                    {
                        if (Includes(table)) table.Truncate(0);
                    }
                }
                return;
            }

            AssertNoWildcards();
            using var doomed = PooledList<Entity>.Rent();
            using (var worldLock = World.Lock())
            {
                foreach (var table in Archetypes)
                {
                    if (!Includes(table)) continue;
                    using var join = table.CrossJoin<C0, C1, C2>(Stream.StreamTypes.AsSpan());
                    if (join.Empty) continue;
                    do
                    {
                        var (s0, s1, s2) = join.Select;
                        Collect(table, s0.Span, s1.Span, s2.Span, doomed);
                    } while (join.Iterate());
                }
            }
            foreach (var entity in doomed)
            {
                if (entity.Alive) World.Despawn(entity);
            }
        }

        private void Collect(Archetype table, Span<C0> span0, Span<C1> span1, Span<C2> span2, PooledList<Entity> doomed)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                if (Pass(in span0[i], in span1[i], in span2[i])) doomed.Add(table[i]);
            }
        }
        #endregion

        #region Action Loops
        private void Loop(Span<C0> span0, Span<C1> span1, Span<C2> span2, ComponentAction<C0, C1, C2> action)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                if (!Pass(in span0[i], in span1[i], in span2[i])) continue;
                action(ref span0[i], ref span1[i], ref span2[i]);
            }
        }

        private void LoopEntity(Archetype table, Span<C0> span0, Span<C1> span1, Span<C2> span2, EntityComponentAction<C0, C1, C2> action)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                if (!Pass(in span0[i], in span1[i], in span2[i])) continue;
                action(new EntityRef(table, i), ref span0[i], ref span1[i], ref span2[i]);
            }
        }

        private void LoopUniform<U>(Span<C0> span0, Span<C1> span1, Span<C2> span2, UniformComponentAction<U, C0, C1, C2> action, U uniform)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                if (!Pass(in span0[i], in span1[i], in span2[i])) continue;
                action(uniform, ref span0[i], ref span1[i], ref span2[i]);
            }
        }

        private void LoopUniformEntity<U>(Archetype table, Span<C0> span0, Span<C1> span1, Span<C2> span2, UniformEntityComponentAction<U, C0, C1, C2> action, U uniform)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                if (!Pass(in span0[i], in span1[i], in span2[i])) continue;
                action(uniform, new EntityRef(table, i), ref span0[i], ref span1[i], ref span2[i]);
            }
        }

        private void LoopDual(Span<C0> span0, Span<C1> span1, Span<C2> span2, ComponentAction<C0, C1, C2> included, ComponentAction<C0, C1, C2> excluded)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                if (Pass(in span0[i], in span1[i], in span2[i])) included(ref span0[i], ref span1[i], ref span2[i]);
                else excluded(ref span0[i], ref span1[i], ref span2[i]);
            }
        }

        private void LoopDualEntity(Archetype table, Span<C0> span0, Span<C1> span1, Span<C2> span2, EntityComponentAction<C0, C1, C2> included, EntityComponentAction<C0, C1, C2> excluded)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                if (Pass(in span0[i], in span1[i], in span2[i])) included(new EntityRef(table, i), ref span0[i], ref span1[i], ref span2[i]);
                else excluded(new EntityRef(table, i), ref span0[i], ref span1[i], ref span2[i]);
            }
        }

        private void LoopDualUniform<U>(Span<C0> span0, Span<C1> span1, Span<C2> span2, UniformComponentAction<U, C0, C1, C2> included, UniformComponentAction<U, C0, C1, C2> excluded, U uniform)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                if (Pass(in span0[i], in span1[i], in span2[i])) included(uniform, ref span0[i], ref span1[i], ref span2[i]);
                else excluded(uniform, ref span0[i], ref span1[i], ref span2[i]);
            }
        }

        private void LoopDualUniformEntity<U>(Archetype table, Span<C0> span0, Span<C1> span1, Span<C2> span2, UniformEntityComponentAction<U, C0, C1, C2> included, UniformEntityComponentAction<U, C0, C1, C2> excluded, U uniform)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                if (Pass(in span0[i], in span1[i], in span2[i])) included(uniform, new EntityRef(table, i), ref span0[i], ref span1[i], ref span2[i]);
                else excluded(uniform, new EntityRef(table, i), ref span0[i], ref span1[i], ref span2[i]);
            }
        }

        private static void LoopAll(Span<C0> span0, Span<C1> span1, Span<C2> span2, ComponentAction<C0, C1, C2> action)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                action(ref span0[i], ref span1[i], ref span2[i]);
            }
        }

        private static void LoopAllEntity(Archetype table, Span<C0> span0, Span<C1> span1, Span<C2> span2, EntityComponentAction<C0, C1, C2> action)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                action(new EntityRef(table, i), ref span0[i], ref span1[i], ref span2[i]);
            }
        }

        private static void LoopAllUniform<U>(Span<C0> span0, Span<C1> span1, Span<C2> span2, UniformComponentAction<U, C0, C1, C2> action, U uniform)
        {
            var length = span0.Length;
            for (var i = 0; i < length; i++)
            {
                action(uniform, ref span0[i], ref span1[i], ref span2[i]);
            }
        }

        private static void LoopAllUniformEntity<U>(Archetype table, Span<C0> span0, Span<C1> span1, Span<C2> span2, UniformEntityComponentAction<U, C0, C1, C2> action, U uniform)
        {
            var length = span0.Length;
